/* Wrapper for toolkit variables */
--color-accent-primary: var(--button-primary-background-color);
--color-accent-primary-hover: var(--button-primary-hover-background-color);
--color-accent-primary-active: var(--button-primary-active-background-color);
--button-text-color-primary: var(--button-primary-text-color);
--button-text-color-primary-hover: var(--button-primary-text-color);
--button-background-color-primary: var(--button-primary-background-color);
--button-background-color-primary-hover: var(--button-primary-hover-background-color);
--button-background-color-primary-active: var(--button-primary-active-background-color);
--button-background-color-primary-disabled: var(--button-background-color-primary);
--button-border-color-primary: var(--button-primary-border-color);
--button-border-color-primary-hover: var(--button-primary-border-color);
--border-radius-medium: var(--button-border-radius);
--input-search-border-radius: var(--button-border-radius);
